"""Render the complete policy-graph experiment, including failures and review notes."""
import argparse,json,html,statistics
from pathlib import Path
ARMS=['vector','multi_query','graph'];NAMES={'vector':'Normal RAG','multi_query':'Multi-query RAG','graph':'Graph RAG'}
def report(out):
 rows=[json.loads(l) for l in (out/'raw.jsonl').read_text().splitlines()];reviews=json.loads((out/'review.json').read_text());qs=json.loads((out/'questions.json').read_text());meta=json.loads((out/'metadata.json').read_text())
 assert len(rows)==84 and len({(r['id'],r['arm']) for r in rows})==84
 assert all(r['id']+'/'+r['arm'] in reviews for r in rows),'Every answer needs review'
 esc=lambda v:html.escape(str(v));pct=lambda x,n:f'{x}/{n} ({100*x/n:.1f}%)' if n else '—'
 def reviewed(r):return reviews[r['id']+'/'+r['arm']]['complete_and_supported']
 slices={'all':rows,'existing':[r for r in rows if r['cohort']=='existing'],'fresh':[r for r in rows if r['cohort']=='fresh']}
 for cat in ['connected','direct','qualification','unavailable']:slices['fresh_'+cat]=[r for r in rows if r['cohort']=='fresh' and r['expected'].get('category')==cat]
 metrics={}
 for label,rs in slices.items():
  metrics[label]={}
  for arm in ARMS:
   rr=[r for r in rs if r['arm']==arm];ans=[r for r in rr if not r['expected'].get('abstain')];neg=[r for r in rr if r['expected'].get('abstain')]
   metrics[label][arm]={'n':len(rr),'answerable_n':len(ans),'reviewed_complete_supported':sum(reviewed(r) for r in ans),'required_facts_correct':sum(reviews[r['id']+'/'+r['arm']].get('required_facts_correct',reviewed(r)) for r in ans),'all_evidence_groups':sum(all(r['group_hits']) for r in ans),'fact_rubric':sum(r['fact_pass'] for r in ans),'negative_n':len(neg),'reviewed_appropriate_negative':sum(reviewed(r) for r in neg),'literal_abstentions':sum(r['response'].get('status')=='abstained' for r in neg),'fallbacks':sum(r['response'].get('status')=='fallback' for r in rr),'http_errors':sum(r['http']!=200 for r in rr),'median_seconds':round(statistics.median(r['seconds'] for r in rr),3) if rr else None,'citation_retries':sum(r['response'].get('attempts',1)>1 for r in rr),'retrieval_degraded':sum(r['retrieval'].get('degraded',False) for r in rr)}
 (out/'metrics.json').write_text(json.dumps(metrics,indent=2))
 ab=json.loads((out/'ablation.json').read_text());abmetrics={}
 for arm in ('full','no_programme_bridge','no_institution_bridge'):
  rr=[r for r in ab if r['arm']==arm and r['cohort']=='fresh' and r['category']=='connected'];abmetrics[arm]={'complete_source_groups':sum(all(r['group_hits']) for r in rr),'n':len(rr)}
 (out/'ablation-metrics.json').write_text(json.dumps(abmetrics,indent=2))
 pair={}
 for arm in ARMS[:2]:
  pair[arm]={'graph_only':0,'baseline_only':0,'both':0,'neither':0}
  for q in qs:
   if q['cohort']!='fresh' or q.get('abstain'):continue
   a=reviews[q['id']+'/'+arm]['complete_and_supported'];g=reviews[q['id']+'/graph']['complete_and_supported'];key='both' if a and g else 'graph_only' if g else 'baseline_only' if a else 'neither';pair[arm][key]+=1
 (out/'paired-results.json').write_text(json.dumps(pair,indent=2))
 lines=['# Programme and policy Graph RAG evaluation','', '29 October 2026 · local Qwen3.5-9B-MLX-4bit · 515 unchanged chunks · 28 questions × 3 retrieval approaches.','', 'The implementation adds source-backed offering → programme → institution → policy paths. Programme identity, entry route, fee category, cycle and source origin qualify retrieval. Complete path evidence is kept together in the prompt. The graph retrieves original source text; it does not contain benchmark answers.','', '| Evaluation slice | Normal RAG | Multi-query RAG | Graph RAG |','|---|---:|---:|---:|']
 table='<table><thead><tr><th>Complete, source-supported answers</th>'+''.join('<th>'+NAMES[a]+'</th>' for a in ARMS)+'</tr></thead><tbody>'
 for label,title in [('all','All answerable'),('existing','Existing questions'),('fresh','Fresh answerable'),('fresh_connected','Fresh connected'),('fresh_direct','Fresh direct controls'),('fresh_qualification','Fresh conditional eligibility')]:
  vals=[pct(metrics[label][a]['reviewed_complete_supported'],metrics[label][a]['answerable_n']) for a in ARMS];lines.append('| '+title+' | '+' | '.join(vals)+' |');table+='<tr><td>'+title+'</td>'+''.join('<td>'+v+'</td>' for v in vals)+'</tr>'
 table+='</tbody></table>'
 lines+=['','These are assistant-reviewed results, not independent or blinded judgments. A pass requires all requested facts and qualifications to be supported by the actual selected evidence. Partial answers and wrong-programme comparisons fail. See review.json for every decision.','', '## Fair comparison and limits','', 'All arms use the same 515 chunks (486 public, 10 student, 19 faculty); evaluation requests have public scope only. The same model, temperature 0, system prompt, 4096-token context limit, 512-token output limit and six-source cap apply. Shared prompt-header compaction applies to every arm. Graph RAG additionally carries graph-derived applicability labels and source dependencies. This evaluates the complete graph-assisted retrieval and packing implementation, not topology alone.','', 'The stronger baseline shares the intent vocabulary and uses the original query plus up to four facet queries, source diversity and reciprocal-rank fusion; it has no graph access. All outputs and actual prompt evidence are retained. Arm positions are balanced using seed 20261029. One API sample per cell is recorded; the existing citation validator can regenerate once. Prefix caching makes latency diagnostic rather than a speed claim.','', 'The 12 existing questions informed debugging. The 16 fresh questions were frozen before implementation and generated once after retrieval was frozen; they were written with knowledge of the domain schema and are development transfer checks, not an independent blind holdout. No retrieval changes followed the fresh results. There is one shared serving fix during the run: nested MLX usage accounting crashed during a citation retry. The first 29 successful cells were retained, the failed existing-question cell was rerun, and no fresh cells had run before this fix. protocol-amendment.json records the hashes.','', '## Automatic proxies and negative controls','', '| Arm | All evidence groups /24 | Fact regex /24 | Appropriate negatives /4 | Literal abstentions /4 | Fallbacks | Median seconds |','|---|---:|---:|---:|---:|---:|---:|']
 for a in ARMS:
  m=metrics['all'][a];lines.append(f"| {NAMES[a]} | {m['all_evidence_groups']} | {m['fact_rubric']} | {m['reviewed_appropriate_negative']} | {m['literal_abstentions']} | {m['fallbacks']} | {m['median_seconds']} |")
 lines+=['','Evidence groups check fixed URL/text patterns, and fact checks use regexes. They are deliberately retained unchanged: equivalent duration evidence can be missed, and an amount from the wrong programme can still match. Do not call either metric semantic accuracy. A supported denial of guaranteed funding can be a correct negative response without literal abstention.','', '## Does traversal contribute?','', '| Retrieval-only ablation on fresh connected questions | Complete fixed source groups /8 |','|---|---:|']
 for a,m in abmetrics.items():lines.append(f"| {a} | {m['complete_source_groups']}/{m['n']} |")
 lines+=['','This ablation removes links while preserving all chunks and fact edges. It measures policy-path evidence coverage before vector fallback, prompt packing or generation. It is not a separately generated answer-accuracy comparison. The full experiment and ablation together show where the graph contributes; shared intent routing and dependency-aware packing also contribute.','', '## Remaining weaknesses','', 'The existing maximum-disciplines question regresses under Graph RAG: it chooses a multiple-programme application rule instead of the maximum-departments rule. A facet match is not always sufficiently precise. The fresh PhD case chooses a mixed-programme duration source and loses to multi-query RAG. The fresh tuition/scholarship/dissertation answer gives the correct numbers but undermines their applicability in a final caveat; it conservatively fails complete-response review. All three approaches get the four direct requested facts right, but multi-query adds unsupported claims in two responses. The separate required_facts_correct metric retains that distinction. The report includes all other misses below. Regex extraction remains tied to supported source layouts, and long bundles can exceed the context budget. Multi-programme comparisons and exhaustive absence claims over fragmented documents are not solved generally.','', 'Access validation: all 515 chunk bytes are unchanged; all graph edges have valid provenance. On the actual rebuilt index, public and student scopes cannot resolve the faculty exam join; faculty can. The full suite passes 279 tests, with 17 integration tests skipped. Local OTP configuration, professor override and model endpoint remain unchanged.','', '## Actual outputs and review','']
 cards=[]
 for q in qs:
  cat=q.get('category','existing');lines+=['### '+q['id']+' — '+q['question'],'',f"Cohort: {q['cohort']}; category: {cat}.",''];card=f'<section id="{q["id"]}" class="case" data-cohort="{q["cohort"]}" data-category="{cat}"><h2>{esc(q["id"])} · {esc(q["question"])}</h2><div class="grid">'
  for arm in ARMS:
   r=next(r for r in rows if r['id']==q['id'] and r['arm']==arm);rv=reviews[q['id']+'/'+arm];d=r['response'];answer=d.get('answer') or '[No answer returned: '+str(d.get('reason',d.get('status')))+']';ok=rv['complete_and_supported'];tag='Pass' if ok else 'Miss'
   lines+=['**'+NAMES[arm]+'** — '+tag+'; '+str(d.get('status')),'',answer,'','Review: '+rv['note'],'']
   card+=f'<article class="{arm}"><h3>{NAMES[arm]} <span class="{"pass" if ok else "miss"}">{tag}</span></h3><p class="answer">{esc(answer)}</p><p class="review">{esc(rv["note"])}</p><details><summary>Inspect evidence, paths and metrics</summary><p>Status: {esc(d.get("status"))} · fact regex: {r["fact_pass"]} · groups: {r["group_hits"]} · {r["seconds"]}s · generation attempts: {d.get("attempts",0)}</p>'
   for p in r['retrieval'].get('graph_proofs',[]):
    if p.get('kind')=='policy':card+='<p class="path">'+esc(' → '.join([p['steps'][0]['from']]+[s['relation']+' '+s['to'] for s in p['steps']]))+'</p>'
   for h in r['selected']:card+=f'<h4>{esc(h["prompt_marker"])} · {esc(h["section"])}</h4><p>{esc(h["text"])}</p><a href="{esc(h["url"])}">Official source</a>'
   card+='</details></article>'
  cards.append(card+'</div></section>')
 (out/'REPORT.md').write_text('\n'.join(lines))
 head='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Policy Graph RAG evaluation</title><style>
:root{color-scheme:light}*{box-sizing:border-box}body{font:15px/1.55 system-ui;background:#f4f6f7;color:#213239;margin:0}main{max-width:1550px;margin:auto;padding:36px}h1{font-size:36px;line-height:1.15;max-width:900px}h2{font-size:20px;line-height:1.4}.intro{max-width:1050px;color:#42565d}.tag{font:12px ui-monospace;color:#41645a;letter-spacing:.08em}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}article,.panel{background:white;border:1px solid #d5e0e4;border-radius:12px;padding:20px}article.graph{border-top:4px solid #23765e}article h3{font-size:16px;margin-top:0}.case{margin:36px 0}.answer{white-space:pre-wrap;overflow-wrap:anywhere}.review{padding-top:12px;border-top:1px solid #dde5e8;font-size:13px;color:#4f626a}.pass,.miss{font-size:11px;float:right;border-radius:12px;padding:3px 9px;background:#e1f1e8;color:#176041}.miss{background:#fff0dc;color:#825321}table{border-collapse:collapse;width:100%;font-size:15px}td,th{text-align:left;padding:12px;border-bottom:1px solid #dce4e8}th{font-size:13px;color:#45616c}tr:last-child td{border-bottom:0}details{font-size:13px;overflow-wrap:anywhere}summary{cursor:pointer;color:#306b60}.path{font:12px/1.6 ui-monospace;background:#edf5f2;padding:8px}.controls{position:sticky;top:0;background:#f4f6f7ed;padding:12px 0;display:flex;gap:8px;flex-wrap:wrap;backdrop-filter:blur(10px)}button{border:1px solid #c4d2d8;background:white;padding:9px 16px;border-radius:20px;cursor:pointer}button.active{background:#214e43;color:white}a{color:#226b62}.small{font-size:13px;color:#526770}pre{white-space:pre-wrap}@media(max-width:950px){.grid{grid-template-columns:1fr}main{padding:20px}h1{font-size:29px}.panel{overflow:auto}table{min-width:600px}}</style><main><div class="tag">LOCAL EVALUATION · 29 OCT 2026</div><h1>Where programme and policy graphs improve RAG</h1><p class="intro">28 questions × 3 retrieval approaches. Same 515 chunks, local Qwen model, context budget and access scope. The graph connects departmental offerings to the correct institute policy, with source-backed programme and cycle qualifications.</p>'''
 links='<p class="small"><a href="REPORT.md">Full report</a> · <a href="metrics.json">Metrics</a> · <a href="raw.jsonl">All raw outputs</a> · <a href="review.json">Review decisions</a> · <a href="metadata.json">Frozen configuration</a> · <a href="ablation.json">Bridge ablation</a></p>'
 notes='<div class="panel"><h2>How to read these results</h2><p>The table scores complete, source-supported answers through assistant review. The fresh set contains 8 connected questions, 4 direct controls, 3 unavailable-information cases and 1 conditional-eligibility case. It was frozen before implementation, but its author knew the schema: this is a development transfer check, not a blind benchmark.</p><p>Multi-query RAG uses the same intent vocabulary and up to four extra vector queries. Graph RAG adds typed paths, applicability labels and dependency-aware packing. No additional content was ingested. All cases, including regressions, appear below.</p><p><strong>Known regression:</strong> the maximum-disciplines question selected a related multiple-programme rule instead of the required limit. A complete graph trace is not a correctness certificate.</p><p class="small">Shared limits: 4096 context tokens · 512 output tokens · 6 sources · temperature 0. One API sample per cell, with the existing optional citation retry. Arm positions are balanced; prefix caching prevents a reliable speed comparison. Nested usage accounting was fixed after 29 cells; retrieval and prompts were unchanged. See the protocol amendment in the full report.</p></div>'
 controls='<nav class="controls">'+''.join(f'<button data-filter="{key}" class="{"active" if key=="all" else ""}">{label}</button>' for key,label in [('all','All questions'),('connected','Fresh connected'),('direct','Direct controls'),('unavailable','Unavailable facts'),('qualification','Conditional eligibility'),('existing','Existing set')])+'</nav>'
 script='''<script>for(const b of document.querySelectorAll('button[data-filter]'))b.onclick=()=>{for(const x of document.querySelectorAll('button'))x.classList.toggle('active',x===b);for(const s of document.querySelectorAll('.case'))s.hidden=!(b.dataset.filter==='all'||s.dataset.category===b.dataset.filter||(b.dataset.filter==='existing'&&s.dataset.cohort==='existing'));};</script>'''
 (out/'comparison.html').write_text(head+links+'<div class="panel">'+table+'</div>'+notes+controls+''.join(cards)+'</main>'+script+'</html>')
 print(json.dumps({'metrics':metrics,'paired':pair,'ablation':abmetrics},indent=2))
if __name__=='__main__':
 ap=argparse.ArgumentParser();ap.add_argument('--out',type=Path,required=True);report(ap.parse_args().out)
